def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter, deque

    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    seen = [[False] * w for _ in range(h)]
    out = [row[:] for row in grid]

    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            touches_edge = False
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                if y == 0 or y == h - 1 or x == 0 or x == w - 1:
                    touches_edge = True
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == bg:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            if not touches_edge:
                fill = 7 if len(cells) == 1 else 2
                for y, x in cells:
                    out[y][x] = fill
    return out
